    private static JsonObject load(String language)throws Exception{try(var stream=LocalText.class.getResourceAsStream("/assets/aerovisuals/lang/"+language+".json")){return JsonParser.parseReader(new java.io.InputStreamReader(stream,StandardCharsets.UTF_8)).getAsJsonObject();}}
    private static void add(String ru,String en,String uk){var entry=new String[]{ru,en,uk};words.put(ru,entry);words.put(en,entry);words.put(uk,entry);}
    public static String get(String value){if(value==null)return null;var a=words.get(value);return a==null?value:a[AeroI18n.isRussian()?0:AeroI18n.isUkrainian()?2:1];}
    public static String pick(String ru,String en,String uk){return AeroI18n.isRussian()?ru:AeroI18n.isUkrainian()?uk:en;}
